      if (getNextMsg(socket, pw, PSWD_SIZE) > 0) {
        isValidUser = AuthenticateUser(nm, pw);
      }
    }
    count++;
  }
  if (isValidUser) {
    return(SUCCESS);
  } else {
    return(FAIL);
  }
}

